// ── VoiceUI: shared helpers to populate + search-filter the TTS voice,
// TTS language (language_boost), and ASR language pickers from the same
// MINIMAX_VOICE_CATALOG, so all three stay consistent and cover MiniMax's
// full catalog instead of a small hand-picked subset. ──────────────────
(function (global) {
  'use strict';

  var CATALOG = global.MINIMAX_VOICE_CATALOG || [];

  /* Populate a <select id="ttsVoice">-style element with one <optgroup>
     per language, one <option> per voice. */
  function populateVoiceSelect(selectEl, opts) {
    opts = opts || {};
    selectEl.innerHTML = '';
    CATALOG.forEach(function (group) {
      var og = document.createElement('optgroup');
      og.label = group.label;
      og.dataset.lang = group.languageBoost;
      group.voices.forEach(function (v) {
        var o = document.createElement('option');
        o.value = v.id;
        o.textContent = v.name;
        og.appendChild(o);
      });
      selectEl.appendChild(og);
    });
    if (opts.preserveValue) selectEl.value = opts.preserveValue;
  }

  /* Populate a <select>-style element with one <option> per language group,
     value = that group's language_boost string (for TTS "语言/language" pickers). */
  function populateLanguageSelect(selectEl, opts) {
    opts = opts || {};
    selectEl.innerHTML = '';
    if (opts.includeAuto) {
      var autoOpt = document.createElement('option');
      autoOpt.value = 'auto';
      autoOpt.textContent = opts.autoLabel || 'Auto';
      selectEl.appendChild(autoOpt);
    }
    CATALOG.forEach(function (group) {
      var o = document.createElement('option');
      o.value = group.languageBoost;
      o.textContent = group.label;
      selectEl.appendChild(o);
    });
    if (opts.preserveValue) selectEl.value = opts.preserveValue;
  }

  /* Populate a <select>-style element with one <option> per language group,
     value = that group's ASR (Web Speech API BCP-47) locale code. */
  function populateAsrSelect(selectEl, opts) {
    opts = opts || {};
    selectEl.innerHTML = '';
    CATALOG.forEach(function (group) {
      var o = document.createElement('option');
      o.value = group.asr;
      o.textContent = group.label;
      selectEl.appendChild(o);
    });
    // 维也纳/慕尼黑这种需要区分同一语言不同地区口音的情况，German 组用
    // de-DE 做主值之外，额外补一个 de-AT 选项方便选择。
    var deOpt = Array.prototype.find.call(selectEl.options, function (o) { return o.value === 'de-DE'; });
    if (deOpt) {
      var extra = document.createElement('option');
      extra.value = 'de-AT';
      extra.textContent = 'Deutsch (Österreich) German (Austria)';
      deOpt.after(extra);
    }
    if (opts.preserveValue) selectEl.value = opts.preserveValue;
  }

  /* Attach a live search box to a <select>: typing hides options/optgroups
     whose text doesn't match, without touching selectEl.value or firing
     spurious change events. Matches against option text and its optgroup
     label, so typing a language name (e.g. "粤语" or "cantonese") also
     surfaces all of that language's voices. */
  function attachFilter(inputEl, selectEl) {
    inputEl.addEventListener('input', function () {
      var q = inputEl.value.trim().toLowerCase();
      var groups = selectEl.querySelectorAll('optgroup');
      if (groups.length) {
        groups.forEach(function (og) {
          var groupMatches = (og.label || '').toLowerCase().indexOf(q) !== -1;
          var anyVisible = false;
          Array.prototype.forEach.call(og.querySelectorAll('option'), function (opt) {
            var show = !q || groupMatches || opt.textContent.toLowerCase().indexOf(q) !== -1;
            opt.hidden = !show;
            if (show) anyVisible = true;
          });
          og.hidden = !anyVisible;
        });
      } else {
        Array.prototype.forEach.call(selectEl.querySelectorAll('option'), function (opt) {
          var show = !q || opt.textContent.toLowerCase().indexOf(q) !== -1;
          opt.hidden = !show;
        });
      }
    });
  }

  global.VoiceUI = {
    catalog: CATALOG,
    populateVoiceSelect: populateVoiceSelect,
    populateLanguageSelect: populateLanguageSelect,
    populateAsrSelect: populateAsrSelect,
    attachFilter: attachFilter,
  };
})(window);
